/// Black-Scholes price by simulation with antithetic variates: (price, standard error).
inline std::tuple<double, double> european_mc(double S0, double K, double r, double sigma, double T, long long n_paths, long long seed, bool is_call) {
    if (n_paths < 2) {
        throw std::invalid_argument("need at least two paths");
    }
    qt::Rng rng(seed);
    qt::Vec z = rng.standard_normal(n_paths);
    double drift = (r - 0.5 * (sigma * sigma)) * T;
    double vol = sigma * std::sqrt(T);
    qt::Vec up = S0 * qt::exp(drift + vol * z);
    qt::Vec down = S0 * qt::exp(drift - vol * z);  // the mirror-image path: cancels much of the noise
    qt::Vec pay{};
    if (is_call) {
        pay = 0.5 * (qt::maximum(up - K, 0.0) + qt::maximum(down - K, 0.0));
    } else {
        pay = 0.5 * (qt::maximum(K - up, 0.0) + qt::maximum(K - down, 0.0));
    }
    double disc = std::exp(-r * T);
    return {disc * qt::mean(pay), disc * qt::std_(pay, 1) / std::sqrt(n_paths)};
}

/// The plain estimator with the normal draws passed in: the other way to make a simulation
/// reproducible across languages.
inline double european_from_draws(const qt::Vec& z, double S0, double K, double r, double sigma, double T) {
    qt::Vec ST = S0 * qt::exp((r - 0.5 * (sigma * sigma)) * T + sigma * std::sqrt(T) * z);
    return std::exp(-r * T) * qt::mean(qt::maximum(ST - K, 0.0));
}

/// Geometric Brownian motion: an n_paths x (n_steps + 1) matrix, one row per path.
inline qt::Mat gbm_paths(double S0, double mu, double sigma, double T, long long n_steps, long long n_paths, qt::Rng& rng) {
    double dt = T / static_cast<double>(n_steps);
    double growth = (mu - 0.5 * (sigma * sigma)) * dt;
    double shock = sigma * std::sqrt(dt);
    qt::Mat paths = qt::zeros(n_paths, qt::iadd(n_steps, 1LL));
    qt::col(paths, 0) = S0;
    for (long long k = 0; k < n_steps; ++k) {
        qt::Vec z = rng.standard_normal(n_paths);  // one draw per path per step, in time order
        qt::col(paths, k + 1) = (qt::col(paths, k) * qt::exp(growth + shock * z)).eval();
    }
    return paths;
}

/// Closed form for the discretely monitored geometric-average Asian call.
inline double geometric_asian_call(double S0, double K, double r, double sigma, double T, long long n_fix) {
    long long n = n_fix;
    double mu = std::log(S0) + (r - 0.5 * (sigma * sigma)) * T * static_cast<double>(qt::iadd(n, 1LL)) / static_cast<double>(qt::imul(2LL, n));
    double var = sigma * sigma * T * static_cast<double>(qt::iadd(n, 1LL)) * static_cast<double>(qt::iadd(qt::imul(2LL, n), 1LL)) / static_cast<double>(qt::imul(qt::imul(6LL, n), n));
    double sd = std::sqrt(var);
    double a = (mu - std::log(K) + var) / sd;
    return std::exp(-r * T) * (std::exp(mu + 0.5 * var) * qt::norm_cdf(a) - K * qt::norm_cdf(a - sd));
}

/// Arithmetic-average Asian call, using the geometric-average option (known exactly) as a
/// control variate: (price, standard error).
inline std::tuple<double, double> asian_call_mc(double S0, double K, double r, double sigma, double T, long long n_steps, long long n_paths, long long seed) {
    if (n_steps < 1 || n_paths < 2) {
        throw std::invalid_argument("need at least one step and two paths");
    }
    qt::Rng rng(seed);
    qt::Mat paths = gbm_paths(S0, r, sigma, T, n_steps, n_paths, rng);
    qt::Mat fixings = qt::block(paths, qt::none, qt::none, 1, qt::none);
    double disc = std::exp(-r * T);
    qt::Vec pay_a = disc * qt::maximum(qt::mean(fixings, 1) - K, 0.0);
    qt::Vec pay_g = disc * qt::maximum(qt::exp(qt::mean(qt::log(fixings), 1)) - K, 0.0);
    qt::Vec da = pay_a - qt::mean(pay_a);
    qt::Vec dg = pay_g - qt::mean(pay_g);
    double var_g = qt::mean(dg * dg);
    double beta = var_g > 0 ? qt::mean(da * dg) / var_g : 0.0;
    qt::Vec adjusted = pay_a - beta * (pay_g - geometric_asian_call(S0, K, r, sigma, T, n_steps));
    return {qt::mean(adjusted), qt::std_(adjusted, 1) / std::sqrt(n_paths)};
}

/// Call that dies if the price is at or below the barrier B on any monitoring date.
inline double down_and_out_call_mc(double S0, double K, double B, double r, double sigma, double T, long long n_steps, long long n_paths, long long seed) {
    qt::Rng rng(seed);
    double dt = T / static_cast<double>(n_steps);
    qt::Vec S = qt::full(n_paths, S0);
    qt::Vec alive = qt::ones(n_paths);
    for (long long _ = 0; _ < n_steps; ++_) {
        qt::Vec z = rng.standard_normal(n_paths);
        S = S * qt::exp((r - 0.5 * (sigma * sigma)) * dt + sigma * std::sqrt(dt) * z);
        alive = qt::where(S <= B, 0.0, alive);
    }
    return std::exp(-r * T) * qt::mean(alive * qt::maximum(S - K, 0.0));
}

/// Heston stochastic volatility, full-truncation Euler scheme on log price.
inline double heston_call_mc(double S0, double K, double r, double v0, double kappa, double theta, double xi, double rho, double T, long long n_steps, long long n_paths, long long seed) {
    if (!(-1.0 <= rho && rho <= 1.0)) {
        throw std::invalid_argument("rho must lie in [-1, 1]");
    }
    qt::Rng rng(seed);
    double dt = T / static_cast<double>(n_steps);
    qt::Vec x = qt::full(n_paths, std::log(S0));
    qt::Vec v = qt::full(n_paths, v0);
    for (long long _ = 0; _ < n_steps; ++_) {
        qt::Vec z1 = rng.standard_normal(n_paths);
        qt::Vec z2 = rng.standard_normal(n_paths);
        qt::Vec w = rho * z1 + std::sqrt(1 - rho * rho) * z2;  // correlated with the price shock
        qt::Vec vp = qt::maximum(v, 0.0);  // full truncation: negative variance is treated as zero
        x = x + (r - 0.5 * vp) * dt + (vp * dt).sqrt() * z1;
        v = v + kappa * (theta - vp) * dt + xi * (vp * dt).sqrt() * w;
    }
    return std::exp(-r * T) * qt::mean(qt::maximum(qt::exp(x) - K, 0.0));
}

/// One-period VaR and expected shortfall for multivariate normal asset returns.
inline std::tuple<double, double> portfolio_var_mc(const qt::Vec& w, const qt::Vec& mu, const qt::Mat& cov, double alpha, long long n_sims, long long seed) {
    qt::Rng rng(seed);
    qt::Mat L = qt::cholesky(cov);
    qt::Mat Z = rng.standard_normal(n_sims, w.size());
    qt::Mat returns = qt::broadcast(qt::matmul(Z, L.transpose()), mu.transpose(), qt::add_op{});  // each row is one scenario of correlated asset returns
    qt::Vec pnl = qt::matvec(returns, w);
    double var = -qt::quantile(pnl, 1 - alpha);
    qt::Mask tail = pnl <= -var;
    double es = -qt::sum(qt::where(tail, pnl, 0.0)) / static_cast<double>(tail.count());
    return {var, es};
}

